-- Album collection 01: only Auth identifies the owner. No client balance writes.
create table brb_private.album_catalog (
 slug text primary key,
 card jsonb not null check(jsonb_typeof(card)='object'),
 active boolean not null default true
);
create table brb_private.album_accounts (
 user_id uuid primary key references auth.users(id) on delete cascade,
 spins integer not null default 10 check(spins>=0),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create table brb_private.album_inventory (
 user_id uuid not null references brb_private.album_accounts(user_id) on delete cascade,
 card_slug text not null references brb_private.album_catalog(slug),
 quantity integer not null check(quantity>0),
 first_received_at timestamptz not null default now(),
 last_received_at timestamptz not null default now(),
 primary key(user_id,card_slug)
);
create table brb_private.album_draws (
 user_id uuid not null references brb_private.album_accounts(user_id) on delete cascade,
 request_id uuid not null,
 card_slug text not null references brb_private.album_catalog(slug),
 duplicate boolean not null,
 created_at timestamptz not null default now(),
 primary key(user_id,request_id)
);
create table brb_private.album_spin_ledger (
 user_id uuid not null references brb_private.album_accounts(user_id) on delete cascade,
 reference text not null,
 delta integer not null check(delta<>0),
 created_at timestamptz not null default now(),
 primary key(user_id,reference)
);
alter table brb_private.album_catalog enable row level security;
alter table brb_private.album_accounts enable row level security;
alter table brb_private.album_inventory enable row level security;
alter table brb_private.album_draws enable row level security;
alter table brb_private.album_spin_ledger enable row level security;
revoke all on brb_private.album_catalog,brb_private.album_accounts,brb_private.album_inventory,brb_private.album_draws,brb_private.album_spin_ledger from public,anon,authenticated;

create function public.brb_album(action text,payload jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); rid uuid; picked text; duplicate boolean; previous integer; wallet integer; result jsonb;
begin
 if u is null then raise exception 'Entre na sua conta para acessar seu álbum.';end if;
 if exists(select 1 from auth.mfa_factors where user_id=u and status='verified')
 and coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then raise exception 'Verifique os dois fatores na sua conta.';end if;
 if payload is null or jsonb_typeof(payload)<>'object' or octet_length(payload::text)>1000
 or action is null or action not in('state','spin') then raise exception 'Pedido inválido.';end if;
 if (action='state' and payload<>'{}'::jsonb) or (action='spin' and (payload-'request_id'<>'{}'::jsonb or not(payload ? 'request_id'))) then raise exception 'Pedido inválido.';end if;
 if action='spin' then
  begin rid:=(payload->>'request_id')::uuid;exception when invalid_text_representation then raise exception 'Pedido inválido.';end;
  if rid is null then raise exception 'Pedido inválido.';end if;
 end if;
 -- Serializes wallet initialization and concurrent draws across devices.
 perform pg_advisory_xact_lock(hashtextextended('brb-album:'||u::text,0));
 insert into brb_private.album_accounts(user_id) values(u) on conflict do nothing;
 insert into brb_private.album_spin_ledger(user_id,reference,delta) values(u,'welcome:collection-01',10) on conflict do nothing;
 select spins into wallet from brb_private.album_accounts where user_id=u for update;
 if action='spin' then
  select d.card_slug,d.duplicate into picked,duplicate from brb_private.album_draws d where d.user_id=u and d.request_id=rid;
  if not found then
   if wallet<=0 then raise exception 'Você não tem giros disponíveis.';end if;
   if exists(select 1 from brb_private.album_draws where user_id=u and created_at>now()-interval '2 seconds') then raise exception 'Aguarde alguns segundos antes de girar novamente.';end if;
   -- Same uniform distribution as the prototype, decided only by the server.
   select slug into picked from brb_private.album_catalog where active order by random() limit 1;
   if picked is null then raise exception 'Não há figurinhas disponíveis no momento.';end if;
   select quantity into previous from brb_private.album_inventory where user_id=u and card_slug=picked;
   duplicate:=coalesce(previous,0)>0;
   update brb_private.album_accounts set spins=spins-1,updated_at=now() where user_id=u returning spins into wallet;
   insert into brb_private.album_inventory(user_id,card_slug,quantity) values(u,picked,1)
    on conflict(user_id,card_slug) do update set quantity=brb_private.album_inventory.quantity+1,last_received_at=now();
   insert into brb_private.album_draws(user_id,request_id,card_slug,duplicate) values(u,rid,picked,duplicate);
   insert into brb_private.album_spin_ledger(user_id,reference,delta) values(u,'draw:'||rid::text,-1);
  end if;
 end if;
 select jsonb_build_object('giros',wallet,'coladas',coalesce((select jsonb_object_agg(card_slug,quantity) from brb_private.album_inventory where user_id=u),'{}'::jsonb),
  'total_draws',(select count(*) from brb_private.album_draws where user_id=u)) into result;
 if action='spin' then result:=result||jsonb_build_object('draw',jsonb_build_object('request_id',rid,'slug',picked,'duplicate',duplicate,'card',(select card from brb_private.album_catalog where slug=picked)));end if;
 return result;
end $$;
revoke all on function public.brb_album(text,jsonb) from public,anon;
grant execute on function public.brb_album(text,jsonb) to authenticated;

